package com.nook.phone;
import android.app.PendingIntent;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.os.Bundle;import android.widget.RemoteViews;import org.json.*;import java.util.*;
public class NookWidget extends AppWidgetProvider {
 private static final Class<?>[] TYPES={NookWidget.class,PetWidget.class,AgentsWidget.class,RequestsWidget.class,UsageWidget.class,TodayWidget.class,CompactWidget.class,DashboardWidget.class,MoodWidget.class};
 private static final String[] KINDS={"status","pet","agents","requests","usage","today","compact","dashboard","mood"};
 private static final Map<Integer,String> rendered=new HashMap<>();
 public static void update(Context c,String status){c.getSharedPreferences("nook",0).edit().putString("status",status).putInt("active",0).putBoolean("waiting",false).apply();refresh(c);}
 public static void updateState(Context c,JSONObject state){
  android.content.SharedPreferences p=c.getSharedPreferences("nook",0);String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());Set<String> finished=new HashSet<>(day.equals(p.getString("day",""))?p.getStringSet("finished",Collections.emptySet()):Collections.emptySet()),observed=new HashSet<>(day.equals(p.getString("day",""))?p.getStringSet("observed",Collections.emptySet()):Collections.emptySet());
  int active=0;JSONArray sessions=state.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject s=sessions.optJSONObject(i);if(s==null)continue;String id=s.optString("id");if(!s.optBoolean("finished")){active++;if(observed.size()<500)observed.add(id);}else if(observed.contains(id)&&finished.size()<500)finished.add(id);}
  boolean waiting=state.optJSONObject("pending")!=null;String copy=waiting?"Review needed":active>0?active+" agents working":"All quiet";int usage=-1;String provider="Usage";JSONArray list=state.optJSONArray("usage");if(list!=null&&list.length()>0){JSONObject first=list.optJSONObject(0);if(first!=null&&!first.isNull("primaryUsed")){usage=Math.max(0,Math.min(100,first.optInt("primaryUsed")));provider=first.optString("title","Usage");}}
  p.edit().putString("day",day).putStringSet("observed",observed).putStringSet("finished",finished).putInt("today",finished.size()).putString("status",copy).putInt("active",active).putBoolean("waiting",waiting).putInt("usage",usage).putString("usage_provider",provider).apply();refresh(c);
 }
 private static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);String status=c.getSharedPreferences("nook",0).getString("status","Open Nook to connect");for(int i=0;i<TYPES.length;i++)renderVariant(c,m,m.getAppWidgetIds(new ComponentName(c,TYPES[i])),status,KINDS[i]);}
 private static Bitmap ring(int percent,boolean dark){Bitmap b=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(14);p.setColor(dark?0xff333643:0xffdfe2ed);canvas.drawCircle(96,96,78,p);if(percent>=0){p.setColor(0xff8799ed);p.setStrokeCap(Paint.Cap.ROUND);canvas.drawArc(18,18,174,174,-90,percent*3.6f,false,p);}p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));p.setTextSize(44);p.setTextAlign(Paint.Align.CENTER);p.setColor(dark?0xffedf0f6:0xff1a2235);canvas.drawText(percent<0?"—":percent+"%",96,111,p);return b;}
 protected static void renderVariant(Context c,AppWidgetManager m,int[] ids,String status,String kind){
  android.content.SharedPreferences p=c.getSharedPreferences("nook",0);boolean waiting=p.getBoolean("waiting",false),connected=!status.equals("Disconnected")&&!status.startsWith("Open Nook");int active=p.getInt("active",0),usage=connected?p.getInt("usage",-1):-1,today=p.getInt("today",0);boolean dark=(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;
  for(int id:ids){Bundle options=m.getAppWidgetOptions(id);boolean wide=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,180)>=240;String key=kind+":"+status+":"+active+":"+waiting+":"+usage+":"+today+":"+wide+":"+dark;if(key.equals(rendered.get(id)))continue;
   int layout=kind.equals("pet")?R.layout.widget_pet:kind.equals("usage")?R.layout.widget_ring:kind.equals("dashboard")&&wide?R.layout.widget_dashboard:R.layout.widget;
   RemoteViews view=new RemoteViews(c.getPackageName(),layout);String copy=!connected?status:kind.equals("agents")?active+" active agents":kind.equals("requests")?(waiting?"Request needs review":"No waiting requests"):kind.equals("today")?today+" sessions completed today*":kind.equals("compact")?(waiting?"Review":active>0?"Working":"Quiet"):kind.equals("mood")?(waiting?"Nook needs you":active>0?"Nook is focused":"Nook is resting"):kind.equals("usage")?(usage<0?"Usage unavailable":p.getString("usage_provider","Usage")+" · 5h used"):status;
   if(!kind.equals("pet"))view.setTextViewText(R.id.widget_status,copy);if(kind.equals("usage"))view.setImageViewBitmap(R.id.widget_ring,ring(usage,dark));if(layout==R.layout.widget_dashboard)view.setTextViewText(R.id.widget_detail,active+" working · "+(waiting?"Review waiting":"No requests")+"\n"+today+" finished today*\n*Observed while connected");
   view.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));m.updateAppWidget(id,view);rendered.put(id,key);
  }
 }
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){renderVariant(c,m,ids,c.getSharedPreferences("nook",0).getString("status","Open Nook to connect"),"status");}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle options){rendered.remove(id);String kind="status";for(int i=0;i<TYPES.length;i++)if(TYPES[i].equals(getClass()))kind=KINDS[i];renderVariant(c,m,new int[]{id},c.getSharedPreferences("nook",0).getString("status","Open Nook to connect"),kind);}
 @Override public void onDeleted(Context c,int[] ids){for(int id:ids)rendered.remove(id);}
}
